quests[7427] = { id = 7427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: MORE DWARVES!" }
quests[7428] = { id = 7428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: MORE ORCS!" }
quests[7429] = { id = 7429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Knot!", progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it.  I think any of the ogres might have it, but I'm not sure if any specific ones do.  Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?!  Is that it there??!", completion = "Oh, thank you for freeing me!  You - ranked number one.  Everyone else - ranked number two or lower.\n\nI knew my life was destined for more than just being an appetizer to some ogre!" }
quests[7441] = { id = 7441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin and the Elder Azj'Tordin", description = "I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.\n\nI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.\n\nFind the imp, Pusillin, and recover my book.\n\nSearch the Warpwood Quarter of Dire Maul for Pusillin.", progress = "I regret nothing, stranger. The Queen has long since passed. The works of the Shen'Dralar have been marred by the madness of Prince Tortheldrin. I seek only freedom... Escape...", completion = "You have found it! A curse upon that miserable imp. Alas, my material possessions are meager at best. You may choose from what I have to offer.", objectives = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\n\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7461] = { id = 7461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Madness Within", description = "Have you heard enough? Are you a <man/woman> of action?\n\nThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.", completion = "We thank you, hero.", objectives = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7462] = { id = 7462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.", sourceObjective = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[7463] = { id = 7463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Refreshment", description = "A {race} mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years!\n\nI have something that will quench your thirst, but first you must do a task for me.\n\n<Lydros snickers.>\n\nThere is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued!\n\nVenture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.", objectives = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7481] = { id = 7481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elven Legends", description = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?", objectives = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7482] = { id = 7482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elven Legends", description = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?", objectives = "Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7483] = { id = 7483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Rapidity", description = "Master Winthalus lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...\n\nRegardless, if you are interested, you will need to present the Libram along with some basic reagents.\n\nHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!\n\n<Lydros shrugs.>", progress = "What is it? I have much cataloguing to do!", completion = "<Lydros yawns.>\n\nAs promised, the Arcanum of Rapidity. Don't spend it all in once place.\n\n<Lydros snickers.>", objectives = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7484] = { id = 7484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Focus", description = "This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old.\n\nThose among you who are more magically inclined might find this item interesting.\n\nThe Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession.\n\nBring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.", progress = "You again? What could you possibly want now?", completion = "Don't hurt yourself when applying the enchantment, {race}.", objectives = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7485] = { id = 7485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Protection", description = "He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.\n\nBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.\n\nOh, and check the north wing.", progress = "My patience prevents your suffering.", completion = "Yes, yes... Calm yourself. As promised, here is your Arcanum.", objectives = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7486] = { id = 7486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Reward", description = "{name}, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.\n\nGo, {name}.  Claim your reward.", completion = "Hydraxis' voice descends from the waters' surface...\n\n\"Choose that which best suits you, {name}.  May it protect you against the foes of the Waterlords.\"", objectives = "Claim your reward from Hydraxis' Coffer.{name}, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer. In it you will find your... reward.\n\nGo, {name}. Claim your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7487] = { id = 7487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attunement to the Core", description = "Rifts stir, tear, and collapse all around us, {race}. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.", objectives = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7488] = { id = 7488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris's Web", description = "The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!\n\nStop her, {name}.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...", progress = "Do you have the web, {name}?  Its concentrated magical energy must be dissipated!", completion = "You retrieved the web!  Well done, {name}!  Lethtendris, like many elves of her ilk, are blind to the dangers the abuse of magic can cause to our world.  They believe they are masters of magic; they do not realize that they are slaves to their own addiction.  Her death saddens me, but it was necessary.\n\nThank you, {name}.  I will have the energies within the web released safely over a wide area, and then I'll destroy it to prevent future magical exploits.", objectives = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7489] = { id = 7489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris's Web", description = "The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies.\n\nLethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.", progress = "{name}, do you have Lethtendris's Web?", completion = "You have done well, {name}.  This web holds within it vast stores of the magic of Dire Maul, and I fear what damage may be unleashed if those energies were harnessed by one so irresponsible as Lethtendris.  I am saddened by her death, but I know that she could never part with her web while alive.\n\nThank you, {name}.  I will send the web to students of magic more responsible than Lethtendris.  They will be the new wardens of its power.", objectives = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7490] = { id = 7490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory for the Horde", description = "You have accomplished the impossible.\n\nThe brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Warchief's advisor Eitrigg.", progress = "<Garrosh's stoic demeanor changes for a split second when he sees the enormous head of Onyxia. The mighty Doomhammer was nearly unsheathed.>", completion = "This is a great victory for the Horde, {name}. So many times you have honored your Warchief. It is time for the Warchief to honor you.", objectives = "Take the Head of Onyxia to Eitrigg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7491] = { id = 7491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For All To See", description = "Overlord Natoj awaits your arrival in the Valley of Strength.\n\n<Eitrigg salutes you.>\n\nDo not keep the Horde waiting!", completion = "Choose your reward and let the celebration of your glorious victory begin.", objectives = "Seek out Overlord Natoj in the Valley of Strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7492] = { id = 7492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Mojache", description = "Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.\n\nServe the Horde, {name}.  Go to Camp Mojache in Feralas and speak with Talo.", completion = "Ah, it is good to see a {class} heed my summons.  I have need of your services, {name}, and fear they will take you down a dangerous path...\n\nA path into Dire Maul.", objectives = "Speak with Talo Thornhoof at Camp Mojache in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7493] = { id = 7493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journey Has Just Begun", objectives = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7494] = { id = 7494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathermoon Stronghold", description = "{name}!  Your aid is needed in Feralas!\n\nAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.\n\nLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.\n\nServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.", completion = "Hail, {name}.  I am pleased to see you, but regret that our meeting is not under more pleasant conditions.\n\nListen close, for I have a vital task for you...", objectives = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7495] = { id = 7495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory for the Alliance", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Grand Admiral in honor of the King.", progress = "By Uther's beard!", completion = "Today, we celebrate this glorious victory!", objectives = "Take the Head of Onyxia to Grand Admiral Jes-Tereth in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7496] = { id = 7496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celebrating Good Times", description = "Seek out Major Mattingly in the Valley of Heroes, {name}. He will be expecting you...", completion = "Few are graced with such ceremony, {name}. Please, choose your reward so that we may begin the celebration.", objectives = "Seek out Major Mattingly in the Valley of Heroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7497] = { id = 7497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journey Has Just Begun", objectives = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
