quests[7507] = { id = 7507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foror's Compendium", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.", objectives = "Return Foror's Compendium of Dragon Slaying to the Athenaeum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7508] = { id = 7508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", description = "If you wish to take on this task, present Lydros with the dull blade.", objectives = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7509] = { id = 7509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.", objectives = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7521] = { id = 7521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderaan the Windseeker", description = "I have told you all that I know, {name}. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form.\n\nDo this and gain the blessing of Thunderaan.", objectives = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Wind Seeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7522] = { id = 7522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examine the Vessel", description = "Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!", objectives = "Examine the Vessel of Rebirth and return it to Highlord Demitrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7541] = { id = 7541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Service to the Horde", objectives = "It will take time for our scholars to study the pendant you brought us.  But for your service to the Horde I would like to offer you a small token.\n\nThank you, {name}.  Your acts bring honor to you, and to us.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7561] = { id = 7561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Thunderfury!", description = "You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.", objectives = "Present the Dormant Wind Kissed Blade to Highlord Demitrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
